"""Expose the close-up massage action with the same published ghost opacity."""
from pathlib import Path
import json,os,sys
BASE=Path(__file__).resolve().parents[2];sys.path.insert(0,str(BASE/'api'));import opacity_assets
out=BASE/'catalog/massage-review';out.mkdir(exist_ok=True);asset=opacity_assets.assets(BASE/'catalog/blender-animations/hands_during_top_hold/guide.png',video=True);relative=os.path.relpath(BASE/asset['folder'],out)
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Massage close-up guide</title><style>body{font:15px/1.6 system-ui;background:#f7f5ef;color:#29404c;margin:24px}main{max-width:900px;margin:auto}.layout{display:grid;grid-template-columns:minmax(240px,360px) 1fr;gap:28px}video{width:100%;background:#f7f5ef;border:1px solid #c3cdd1;border-radius:8px}h1{font-size:28px}a{color:#326881}@media(max-width:650px){.layout{grid-template-columns:1fr}}</style><main><a href="../animations.html#hands_during_top_hold">All guide animations</a><h1>Massage close-up</h1><div class="layout"><video controls playsinline loop preload="metadata" poster="POSTER"><source src="VIDEO" type="video/mp4"></video><section><p>Keep the camera still. Frame one practitioner hand and a small curved area of the back.</p><p>The hand settles into contact, presses and glides forward, then eases back and releases. The surface compresses beneath the palm. Faint contour lines and a small warm contact cue make the action readable.</p><p>6.8 seconds · one anatomical hand · 65% overlay opacity. The back surface and forearm extend beyond the picture; there is no full-body model.</p><p><a href="ANIMATION">Transparent animation</a> · <a href="STRIP">Frame samples</a> · <a href="report.md">Checks and implementation</a></p></section></div></main></html>'''
for name,field in [('POSTER','poster'),('VIDEO','video'),('ANIMATION','overlay'),('STRIP','strip')]:page=page.replace(name,os.path.relpath(BASE/asset[field],out))
